<template>
  <section class="market-agent-map" aria-label="Market specialist map"><header><h2>Specialist map</h2><span>{{ specialists.length }} registered roles</span></header>
    <svg v-if="nodes.length" viewBox="0 0 920 430" role="group" aria-label="Registered market research specialists"><line v-for="node in nodes.filter(n=>n.id!==selectedId&&n.family===selected?.family)" :key="node.id" :x1="selectedPoint?.x" :y1="selectedPoint?.y" :x2="node.x" :y2="node.y"/><g v-for="node in nodes" :key="node.id" :transform="`translate(${node.x},${node.y})`" role="button" tabindex="0" :aria-label="node.name" :aria-pressed="selectedId===node.id" :data-market-agent="node.id" :class="{selected:selectedId===node.id}" @click="selectedId=node.id" @keydown.enter="selectedId=node.id" @keydown.space.prevent="selectedId=node.id"><title>{{ node.name }}</title><circle class="halo" r="20"/><circle r="14" :fill="selectedId===node.id?'#ed7844':'#8393a4'"/><text text-anchor="middle" y="4">{{ node.displayNumber }}</text></g></svg>
    <p v-else class="map-note">Loading the specialist registry…</p><label>Find a specialist<select v-model="selectedId" aria-label="Find a market specialist"><option v-for="role in specialists" :key="role.id" :value="role.id">{{ role.name }}</option></select></label>
    <div v-if="selected" class="market-specialist-detail"><h3>{{ selected.name }}</h3><small>{{ selected.family.replaceAll('_',' ') }}</small><p>{{ selected.focus }}</p><div class="specialist-facts"><div><span>Required capability</span><strong>{{ selected.capability?.replaceAll('_',' ') }}</strong></div><div><span>Related strategy definitions</span><strong>{{ related.length }}</strong></div><div v-if="snapshot"><span>Rules with usable inputs</span><strong>{{ related.filter(x=>x.status==='active').length }}</strong></div></div><details v-if="related.length"><summary>Inspect this family’s rules and evidence</summary><article v-for="item in related.slice(0,8)" :key="item.id"><h4>{{ item.name }}</h4><p>{{ item.rule }}</p><p class="rule-status">{{ item.status || 'Registered definition' }}<template v-if="item.missing?.length"> · Missing {{ item.missing.join(', ') }}</template></p></article></details><p class="map-note">This snapshot stores measured inputs and rule signals. Agent questions and replies are shown in Chart Lab when a discussion has been recorded.</p><RouterLink to="/chart-lab">Open Chart Lab →</RouterLink></div>
  </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue'
import {spreadNodes} from '../utils/presentationGraphs.mjs'
const props=defineProps({specialists:{type:Array,default:()=>[]},catalog:{type:Array,default:()=>[]},snapshot:{type:Object,default:null}})
const selectedId=ref('')
const nodes=computed(()=>spreadNodes(props.specialists))
const selected=computed(()=>props.specialists.find(x=>x.id===selectedId.value))
const selectedPoint=computed(()=>nodes.value.find(x=>x.id===selectedId.value))
const related=computed(()=>(props.snapshot?.strategies||props.catalog).filter(x=>x.family===selected.value?.family))
watch(()=>props.specialists,rows=>{if(!rows.some(x=>x.id===selectedId.value))selectedId.value=rows[0]?.id||''},{immediate:true})
</script>
<style scoped>
.market-agent-map{background:#f8fafc;border:1px solid #f0f3f7;border-radius:12px;overflow:hidden;min-width:0}.market-agent-map>header{padding:17px 19px 12px;display:flex;justify-content:space-between;gap:15px;align-items:center}.market-agent-map h2{font-size:18px!important;font-weight:550;margin:0!important}.market-agent-map header>span{font-size:10px;color:#697589}.market-agent-map>svg{display:block;width:100%;height:280px}.market-agent-map line{stroke:#e8b69d;stroke-width:1.3}.market-agent-map g[role=button]{cursor:pointer;outline:none}.market-agent-map .halo{fill:transparent;stroke:transparent;stroke-width:2}.market-agent-map .selected .halo,.market-agent-map g:focus .halo{stroke:#ed7844}.market-agent-map text{font-size:12px;fill:white;pointer-events:none}.market-agent-map>label{padding:0 19px 16px;font-size:11px!important;display:flex!important;flex-direction:row!important;align-items:center;gap:10px}.market-agent-map>label select{flex:1;min-width:0;max-width:100%;font-size:11px!important;padding:7px 8px!important;min-height:33px!important}.market-specialist-detail{border-top:1px solid #e9edf2;background:white;padding:17px 19px;max-height:430px;overflow:auto}.market-specialist-detail h3{font-size:16px!important;margin:0 0 6px!important;font-weight:550}.market-specialist-detail small{font-size:10px;color:#697589}.market-specialist-detail>p{font-size:13px;line-height:1.8;color:#52657a;margin-top:13px}.specialist-facts{margin:15px 0;font-size:11px}.specialist-facts>div{display:flex;justify-content:space-between;gap:20px;padding:8px 0;border-bottom:1px solid #edf0f4}.specialist-facts span{color:#697589}.specialist-facts strong{font-weight:500}.market-specialist-detail summary{font-size:11px;cursor:pointer}.market-specialist-detail article{padding:13px 0;border-bottom:1px solid #edf0f4}.market-specialist-detail h4{font-size:12px;font-weight:500;margin:0 0 6px}.market-specialist-detail article p{font-size:12px;line-height:1.7}.rule-status{color:#697589;font-size:10px!important;margin-top:9px}.market-specialist-detail .map-note,.map-note{font-size:11px;color:#697589;line-height:1.7}.market-specialist-detail>a{font-size:11px;display:inline-block;margin-top:13px}@media(max-width:600px){.market-agent-map>header,.market-agent-map>label{padding-left:13px;padding-right:13px}.market-agent-map>svg{height:235px}.market-specialist-detail{padding:15px 13px}}
</style>
